// Halving the shared-memory footprint (35.8KB -> 17.9KB per CTA) removes the
// smem occupancy limit, raising SM occupancy from 33% to ~67% so cross-CTA
// overlap hides the global-load latency. Scalar bounded path kept for other n.
.version 7.8
.target sm_89
.address_size 64
.visible .entry triu_matmul_kernel(
    .param .u64 triu_matmul_kernel_param_0,
    .param .u64 triu_matmul_kernel_param_1,
