    ld.param.u64 %rd2, [triu_matmul_kernel_param_1];
    ld.param.u64 %rd3, [triu_matmul_kernel_param_2];
    ld.param.u32 %r7,  [triu_matmul_kernel_param_3];
    mov.u32 %r1, %tid.x;
    mov.u32 %r2, %tid.y;
    mov.u32 %r3, %ctaid.x;
    mov.u32 %r4, %ctaid.y;
    shl.b32 %r5, %r3, 6;
    shl.b32 %r6, %r4, 6;
    shl.b32 %r9, %r2, 2;
    shl.b32 %r10, %r1, 2;
    add.s32 %r11, %r6, %r9;
    add.s32 %r12, %r5, %r10;
    add.s32 %r8, %r5, 63;
    setp.lt.s32 %p1, %r8, %r6;
    @%p1 bra WRITE_ZERO;
    mov.f32 %f1, 0f00000000;
    mov.f32 %f2, 0f00000000;
    mov.f32 %f3, 0f00000000;
    mov.f32 %f4, 0f00000000;
    mov.f32 %f5, 0f00000000;
    mov.f32 %f6, 0f00000000;
    mov.f32 %f7, 0f00000000;
    mov.f32 %f8, 0f00000000;
    mov.f32 %f9, 0f00000000;
    mov.f32 %f10, 0f00000000;
    mov.f32 %f11, 0f00000000;
    mov.f32 %f12, 0f00000000;
    mov.f32 %f13, 0f00000000;
    mov.f32 %f14, 0f00000000;
    mov.f32 %f15, 0f00000000;
    mov.f32 %f16, 0f00000000;
    shl.b32 %r14, %r2, 4;
    add.s32 %r14, %r14, %r1;
    mov.u64 %rd10, tile_a;
    mov.u64 %rd11, tile_b;
    mov.u64 %rd20, %rd10;
    mov.u64 %rd21, %rd11;
    mov.u32 %r13, %r6;
    and.b32 %r22, %r7, 63;
    setp.eq.s32 %p8, %r22, 0;
    @!%p8 bra SCALAR_FIRST;
    mov.u32 %r15, %r14;
FP_LOAD_LOOP:
    shr.u32 %r16, %r15, 3;
    and.b32 %r17, %r15, 7;
    shl.b32 %r17, %r17, 2;
    mul.lo.s32 %r20, %r16, 36;
    add.s32 %r20, %r20, %r17;
    shl.b32 %r21, %r20, 2;
    cvt.u64.u32 %rd12, %r21;
