    add.s64 %rd9, %rd20, %rd12;
    cp.async.cg.shared.global [%rd9], [%rd8], 16;
    shr.u32 %r16, %r15, 4;
    and.b32 %r17, %r15, 15;
    shl.b32 %r17, %r17, 2;
    mul.lo.s32 %r20, %r16, 68;
    add.s32 %r20, %r20, %r17;
