    add.s64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.s64 %rd8, %rd2, %rd7;
    ld.global.f32 %f25, [%rd8];
S0_B_DONE:
    add.s64 %rd9, %rd21, %rd12;
    st.shared.f32 [%rd9], %f25;
    add.s32 %r15, %r15, 256;
    setp.lt.s32 %p5, %r15, 2048;
    @%p5 bra S_LOAD0_LOOP;
TOP:
    @%p8 cp.async.wait_group 0;
